    if (k === 'move') return { drive: -2, cort: -2, delay: { drive: 15, cort: -8, note: '💡 Нагрузка запустила эндорфины — своё обезболивающее мозга, работает как дофамин. Тело будто выдохнуло.' } };
    if (k === 'brave') return { drive: 3, cort: 6, delay: { drive: 14, cort: -9, note: '💡 Страшно-но-не-опасно: адреналин схлынул за минуты, а эндорфины и гордость «я смог» остались — награда держится дольше страха.' } };
